package dev.kelmagic.client;
import dev.kelmagic.KelMagic;import java.util.*;import net.minecraft.client.*;import net.minecraft.client.gui.*;import net.minecraft.client.gui.screens.*;import net.minecraft.network.chat.Component;import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.nbt.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockState;import com.mojang.math.Axis;import net.neoforged.api.distmarker.Dist;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.bus.api.SubscribeEvent;
/** Optional native block-model renderer, never shipped in JAR. */
@EventBusSubscriber(modid=KelMagic.MODID,value=Dist.CLIENT)public final class QaStructures {
 static boolean opened;static int wait,stage,frames;static Screen screen;static final String[] BIOMES={"plains","desert","taiga","snowy","savanna"};
 @SubscribeEvent public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("kelmagic.structureQA")||stage>=10)return;var mc=Minecraft.getInstance();if(mc.level==null){if(!opened&&mc.screen instanceof TitleScreen&&++wait>40){opened=true;mc.createWorldOpenFlows().openWorld(System.getProperty("kelmagic.qaWorld","KelMagicQA"),()->{});}return;}if(screen==null){mc.options.guiScale().set(1);mc.resizeDisplay();screen=new Scene();}mc.setScreen(screen);if(++frames==12){var dir=new java.io.File("/data/native-qa-1.14");dir.mkdirs();Screenshot.grab(dir,String.format("archive-%02d.png",stage),mc.getMainRenderTarget(),m->{});}if(frames>=20){frames=0;if(stage==9&&Boolean.getBoolean("kelmagic.locateQA")&&!QaLocate.done)return;if(++stage==10){System.out.println("STRUCTURE_NATIVE_QA_114_COMPLETE");mc.stop();}}}
 record Block(BlockPos pos,BlockState state){}record Building(List<Block> blocks,int width,int depth){}
 static final Map<String,Building> CACHE=new HashMap<>();
 static Building load(String id){return CACHE.computeIfAbsent(id,k->{try{var n=NbtIo.readCompressed(java.nio.file.Path.of("../src/main/resources/data/kelmagic/structure/archive/"+id+".nbt"),NbtAccounter.unlimitedHeap());var palette=n.getList("palette",10);var states=new ArrayList<BlockState>();for(int i=0;i<palette.size();i++)states.add(NbtUtils.readBlockState(BuiltInRegistries.BLOCK.asLookup(),palette.getCompound(i)));var list=n.getList("blocks",10);var blocks=new ArrayList<Block>();for(int i=0;i<list.size();i++){var entry=list.getCompound(i);var p=entry.getList("pos",3);var state=states.get(entry.getInt("state"));if(state.is(Blocks.JIGSAW))state=BuiltInRegistries.BLOCK.get(ResourceLocation.parse(entry.getCompound("nbt").getString("final_state"))).defaultBlockState();blocks.add(new Block(new BlockPos(p.getInt(0),p.getInt(1),p.getInt(2)),state));}var size=n.getList("size",3);return new Building(blocks,size.getInt(0),size.getInt(2));}catch(Exception ex){throw new IllegalStateException(ex);}});}
 static class Scene extends Screen {Scene(){super(Component.literal("Archive native models"));}public boolean isPauseScreen(){return false;}public void render(GuiGraphics g,int x,int y,float p){g.fill(0,0,width,height,0xFFE7E0D0);String biome=BIOMES[stage%5];boolean cutaway=stage>=5;g.drawString(font,"Archive: "+biome+" / "+(cutaway?"interior cutaway":"native stair-roof geometry"),24,25,0x293C38,false);var mc=Minecraft.getInstance();for(int v=1;v<=3;v++){var b=load(biome+"_"+v);g.pose().pushPose();g.pose().translate(220+(v-1)*420,670,500);g.pose().scale(14,-14,14);g.pose().mulPose(Axis.XP.rotationDegrees(28));g.pose().mulPose(Axis.YP.rotationDegrees(45));g.pose().translate(-b.width/2f,0,-b.depth/2f);for(var block:b.blocks){var at=block.pos;if(block.state.isAir()||cutaway&&(at.getY()>=5||at.getZ()==1&&at.getY()>0||at.getX()==1&&at.getY()>0))continue;g.pose().pushPose();g.pose().translate(at.getX(),at.getY(),at.getZ());mc.getBlockRenderer().renderSingleBlock(block.state,g.pose(),mc.renderBuffers().bufferSource(),0xF000F0,net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY);g.pose().popPose();}mc.renderBuffers().bufferSource().endBatch();g.pose().popPose();g.drawString(font,List.of("Reading hall","Double-stack library","Hall and private study").get(v-1),100+(v-1)*420,760,0x293C38,false);}}}
}
